// ===========================
// 制度の計算機 — 子ども・子育て支援金（いくら引かれる）の値の表（値・出典・確認日をセットで）
// どの値も下の SOURCES の原文（こども家庭庁のページと PDF、協会けんぽの保険料額表、e-Gov 法令検索）を 2026-09-25 に読んで写した。
// 標準報酬月額の等級表は育休の計算と同じもの（lib/ikukyu-values.js の hoken.hyojunKenpo）を使い、ここには写さない。
// 令和9年度（2027年4月分）からの支援金率は 2026-09-25 時点で決まっていない。国の「見込み」は率ではなく平均の額なので、
// 計算には使わず、表として出すだけにする（MIKOMI）。
// ブラウザでは window.ShienkinValues、Node（テスト）では module.exports で使う
// ===========================
(function (root) {
  'use strict';

  var CHECKED = '2026-09-25';   // 下の出典を最後に原文で確かめた日
  var CFA = 'https://www.cfa.go.jp/';
  var CFA_PDF = CFA + 'assets/contents/node/basic_page/field_ref_resources/fb3dbb28-102a-4840-90a5-00ad2e0d117f/';
  var KK = 'https://www.kyoukaikenpo.or.jp/';
  var EGOV = 'https://laws.e-gov.go.jp/law/';

  var SOURCES = [
    { key: 'cfa', label: 'こども家庭庁「子ども・子育て支援金制度について」', url: CFA + 'policies/kodomokosodateshienkinseido', where: '被用者保険は標準報酬月額 × 支援金率。令和8年度の一律の支援金率は0.23%、基本的に半分は企業が負担。令和8年4月保険料（5月に給与天引き）から。国保は市町村の条例、後期高齢者医療は広域連合の条例で決まり、率は市町村・広域連合ごとに違う' },
    { key: 'cfaFaq', label: 'こども家庭庁「子ども・子育て支援金制度の概要（FAQ）」', url: CFA + 'policies/kodomokosodateshienkin/faq', where: '（その他）(2) 賞与からも拠出（健康保険・厚生年金と同様）、(3) 企業の従業員は育児休業中は免除' },
    { key: 'leafHiyosha', label: 'こども家庭庁 被用者保険加入者向けリーフレット（令和8年4月1日更新）', url: CFA_PDF + '5d364161/20260324policies-kodomokosodateshienkinseido-12.pdf', where: '支援金率0.23%。支援金額（月額）＝標準報酬月額 × 支援金率、賞与は標準賞与 × 支援金率。医療保険の保険料とあわせて徴収。国保・後期は被保険者だけが負担' },
    { key: 'leafJigyo', label: 'こども家庭庁 事業主向けリーフレット（令和8年4月1日更新）', url: CFA_PDF + 'ae51fa59/20260324policies-kodomokosodateshienkinseido-14.pdf', where: '給与明細に内訳として支援金額を示すことは法令上の義務ではない（記載への協力のお願い）。育休・産休中は免除。海外赴任中も日本の健康保険に入っていれば拠出' },
    { key: 'leafKokuho', label: 'こども家庭庁 国民健康保険・後期高齢者医療制度加入者向けリーフレット（令和8年4月1日更新）', url: CFA_PDF + '419b6d0e/20260324policies-kodomokosodateshienkinseido-13.pdf', where: '所得割と均等割は市町村ごと。18歳に達する日以後の最初の3月31日までのこどもは均等割が全額軽減。低所得の人には軽減措置' },
    { key: 'shisan8', label: 'こども家庭庁「医療保険制度ごとの年収別試算」（令和8年度、令和8年2月6日差替え）', url: CFA_PDF + '7891820b/20260206policies-kodomokosodateshienkinseido-05.pdf', where: '被用者保険 年収200万円 月192円〜1,000万円 959円（年収 × 0.23% ÷ 12 × 1/2）。国保（夫婦と子の世帯・片方だけ給与収入）年収80万円 50円〜300万円 650円。後期高齢者（単身・年金収入のみ）80万円 50円〜200万円 200円。国保・後期は50円丸めのモデル試算' },
    { key: 'mikomi', label: 'こども家庭庁「子ども・子育て支援金に関する試算（医療保険加入者一人当たり平均月額）」（令和7年12月26日）', url: CFA_PDF + 'e7968b5b/20251226policies-kodomokosodateshienkinseido-03.pdf', where: '全制度平均 令和8年度250円・9年度350円・10年度450円。協会けんぽの被保険者一人当たり 450円・550円・700円など。令和10年度の被用者保険 9,000億円 ÷ 令和4年度の総報酬227兆円 ＝ 0.4%（本人0.2%）の機械的な計算。結果は相当程度の幅をもってみる必要がある' },
    { key: 'kkRate', label: '協会けんぽ「協会けんぽの子ども・子育て支援金率について」', url: KK + 'about/business/insurance_rate/003/index.html', where: '一般被保険者 令和8年4月分（5月納付分）から0.23%。任意継続被保険者・日雇特例被保険者は令和8年4月分（4月納付分）から0.23%' },
    { key: 'kkTable', label: '協会けんぽ「令和8年3月分（4月納付分）からの健康保険・厚生年金保険の保険料額表」（東京支部）', url: KK + 'assets/R8_13tokyo.pdf', where: '子ども・子育て支援金の欄（0.23%）の全額・折半額（例 標準報酬月額300,000円 → 690.0円・345.0円）。給与から控除するときの被保険者負担分は50銭以下切り捨て・50銭超切り上げ（特約があれば特約）。標準賞与額は1,000円未満切り捨て、健康保険・介護保険・支援金の上限は年度の累計573万円。任意継続被保険者の標準報酬月額の上限は320,000円（令和8年度）' },
    { key: 'kenpo', label: '健康保険法（e-Gov 法令検索）', url: EGOV + '211AC0000000070', where: '156条（一般保険料等額 ＝ 標準報酬月額・標準賞与額 ×（一般保険料率＋子ども・子育て支援金率））、160条の2（支援金率は政令で定める率の範囲内で保険者が定める）、161条（被保険者と事業主が2分の1ずつ。任意継続被保険者は全額）、162条（健康保険組合は規約で事業主の負担割合を増やせる）' },
    { key: 'kenpoRei', label: '健康保険法施行令（e-Gov 法令検索）', url: EGOV + '215IO0000000243', where: '45条の5（子ども・子育て支援金率の上限は1000分の2.5）' },
    { key: 'shotoku', label: '所得税法（e-Gov 法令検索）', url: EGOV + '340AC0000000033', where: '74条2項（社会保険料控除の対象: 1号 健康保険の保険料、2号 国民健康保険の保険料・国民健康保険税、2号の2 後期高齢者医療の保険料）' },
    { key: 'kokuho', label: '国民健康保険法（e-Gov 法令検索）', url: EGOV + '333AC0000000192', where: '76条（保険料で子ども・子育て支援納付金の納付に要する費用を含めて徴収）' },
  ];

  // 令和9年度以降の見込み（加入者・被保険者・世帯の一人当たり平均の月額。50円丸め。こども家庭庁の試算、令和7年12月26日）
  // 率ではないので、個人の額の計算には使わない
  var MIKOMI = {
    years: ['令和8年度', '令和9年度', '令和10年度'],   // 令和8年度は試算、9・10年度は見込み
    rows: [
      { label: '協会けんぽ（被保険者1人）', v: [450, 550, 700] },
      { label: '健保組合（被保険者1人）', v: [550, 700, 900] },
      { label: '共済組合（被保険者1人）', v: [650, 800, 1000] },
      { label: '国民健康保険（1世帯）', v: [300, 450, 550] },
      { label: '後期高齢者医療（1人）', v: [200, 250, 350] },
      { label: '全制度平均（加入者1人）', v: [250, 350, 450] },
    ],
    // 令和10年度の被用者保険について国が示した機械的な計算: 9,000億円 ÷ 総報酬227兆円（令和4年度）≒ 0.4%、本人0.2%
    refRate2028: 0.4,
  };

  // 国保・後期高齢者医療の令和8年度のモデル試算（月額・50円丸め）。実際は市町村・広域連合の条例で決まる
  var MODEL8 = {
    kokuho: { note: '夫婦と子の世帯（夫婦の片方だけに給与収入）の一世帯当たり', rows: [[80, 50], [100, 50], [150, 250], [200, 400], [250, 550], [300, 650]] },
    kouki: { note: '単身世帯（年金収入のみ）の一人当たり', rows: [[80, 50], [100, 50], [125, 50], [150, 50], [175, 100], [200, 200]] },
    // 被用者保険の年収別（年収 ＝ 標準報酬総額。× 0.23% ÷ 12 × 1/2。国の表の値）
    hiyosha: [[200, 192], [400, 384], [600, 575], [800, 767], [1000, 959]],
  };

  var V = {
    CHECKED: CHECKED,
    STALE_MONTHS: 12,             // 確認日からこの月数がたったら画面に注意を出す（令和9年度の率は 2027 年春に出るはず）
    SOURCES: SOURCES,

    fiscalYear: '令和8年度',      // この率が使われる期間（2026年4月分〜2027年3月分）
    rateFrom: '2026-04',          // 4月分の保険料から（会社員は5月の給与から引かれる）
    rateTo: '2027-03',            // 令和9年度の率は未定。4月を過ぎたら画面に注意を出す
    rate: 0.23,                   // 子ども・子育て支援金率（%。労使の合計。被用者保険に国が示す一律の率）
    rateCap: 0.25,                // 健康保険法施行令45条の5 の上限（%）
    bonusCapYear: 5730000,        // 標準賞与額の年度の累計の上限（健康保険・介護保険・支援金と同じ）
    bonusUnit: 1000,              // 標準賞与額は 1,000円未満切り捨て
    ninkeiMax: 320000,            // 協会けんぽの任意継続被保険者の標準報酬月額の上限（令和8年度）
    // 令和8年（2026年1〜12月）に引かれる月数（年末調整の社会保険料に入る分）
    //   会社員: 4月分〜11月分を 5〜12月の給与から（前月分を翌月の給与から引く。こども家庭庁「4月保険料（5月に給与天引き）」）
    //   任意継続: 4月分〜12月分をその月に納める（協会けんぽ「4月分（4月納付分）から」）
    monthsIn2026: { kaisha: 8, ninkei: 9 },

    MIKOMI: MIKOMI,
    MODEL8: MODEL8,
  };

  if (typeof module !== 'undefined' && module.exports) module.exports = V;
  else root.ShienkinValues = V;
})(this);
